  "id" TEXT COLLATE "C" NOT NULL,
  "participation_set" TEXT COLLATE "C" NOT NULL,
  "eligibility_at" TEXT COLLATE "C" NOT NULL,
  "electors" TEXT COLLATE "C" NOT NULL,
  "rule" TEXT COLLATE "C" NOT NULL,
  "rule_version" TEXT COLLATE "C" NOT NULL,
  "threshold" BIGINT NOT NULL,
  "option_count" BIGINT NOT NULL,
  "deadline" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C",
  "evaluation" TEXT COLLATE "C",
  "reconsideration" TEXT COLLATE "C",
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "participation_set") REFERENCES participation_set ("tenant", "id"),
  FOREIGN KEY ("tenant", "electors") REFERENCES decision_elector ("tenant", "id"),
  FOREIGN KEY ("tenant", "reconsideration") REFERENCES decision_case ("tenant", "id")
);

CREATE TABLE decision_option (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "decision_case" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "label" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision_case") REFERENCES decision_case ("tenant", "id")
);

CREATE TABLE decision_event (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "decision_case" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "previous" TEXT COLLATE "C",
  "kind" TEXT COLLATE "C" NOT NULL,
  "response" TEXT COLLATE "C",
  "outcome" TEXT COLLATE "C",
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision_case") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "previous") REFERENCES decision_event ("tenant", "id")
);

CREATE TABLE decision_outcome (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "decision_case" TEXT COLLATE "C" NOT NULL,
  "selected" TEXT COLLATE "C" NOT NULL,
  "responses" TEXT COLLATE "C" NOT NULL,
  "snapshot_digest" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision_case") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "selected") REFERENCES decision_option ("tenant", "id")
);

CREATE TABLE decision_outcome_member (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "response" TEXT COLLATE "C" NOT NULL,
  "next" TEXT COLLATE "C",
  "depth" BIGINT NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "next") REFERENCES decision_outcome_member ("tenant", "id")
);

CREATE TABLE decision_response (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "decision_case" TEXT COLLATE "C" NOT NULL,
  "voter" TEXT COLLATE "C" NOT NULL,
  "ranking" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C",
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision_case") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "voter") REFERENCES participation ("tenant", "id")
);

CREATE TABLE evaluation_finish (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "run" TEXT COLLATE "C" NOT NULL,
  "start" TEXT COLLATE "C",
  "outcome" TEXT COLLATE "C" NOT NULL,
  "finished_at" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C",
  "reason" TEXT COLLATE "C" NOT NULL,
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "run") REFERENCES evaluation_run ("tenant", "id"),
  FOREIGN KEY ("tenant", "start") REFERENCES evaluation_start ("tenant", "id")
);

CREATE TABLE evidence_bundle (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "key_" TEXT COLLATE "C" NOT NULL,
  "label" TEXT COLLATE "C" NOT NULL,
  "predecessor" TEXT COLLATE "C",
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id")
);

CREATE TABLE evidence_item (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "bundle" TEXT COLLATE "C" NOT NULL,
  "source" TEXT COLLATE "C" NOT NULL,
  "source_record" TEXT COLLATE "C" NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "observed_at" TEXT COLLATE "C" NOT NULL,
  "revision" TEXT COLLATE "C",
  "digest" TEXT COLLATE "C",
  "provenance" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "bundle") REFERENCES evidence_bundle ("tenant", "id"),
  FOREIGN KEY ("tenant", "source") REFERENCES evidence_source ("tenant", "id"),
  FOREIGN KEY ("tenant", "revision") REFERENCES artifact_revision ("tenant", "id")
);

CREATE TABLE evidence_member (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "bundle" TEXT COLLATE "C" NOT NULL,
  "item" TEXT COLLATE "C" NOT NULL,
  "next" TEXT COLLATE "C",
  "depth" BIGINT NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "bundle") REFERENCES evidence_bundle ("tenant", "id"),
  FOREIGN KEY ("tenant", "item") REFERENCES evidence_item ("tenant", "id"),
  FOREIGN KEY ("tenant", "next") REFERENCES evidence_member ("tenant", "id")
);

CREATE TABLE evidence_seal (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "bundle" TEXT COLLATE "C" NOT NULL,
  "head" TEXT COLLATE "C",
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "bundle") REFERENCES evidence_bundle ("tenant", "id"),
  FOREIGN KEY ("tenant", "head") REFERENCES evidence_member ("tenant", "id")
);

CREATE TABLE fulfillment (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "fulfillment_set" TEXT COLLATE "C" NOT NULL,
  "ordinal" BIGINT NOT NULL,
  "specification_pin" TEXT COLLATE "C",
  "executor" TEXT COLLATE "C" NOT NULL,
  "requested_at" TEXT COLLATE "C" NOT NULL,
  "evidence" TEXT COLLATE "C",
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment_set") REFERENCES fulfillment_set ("tenant", "id"),
  FOREIGN KEY ("tenant", "specification_pin") REFERENCES specification_pin ("tenant", "id"),
  FOREIGN KEY ("tenant", "executor") REFERENCES fulfillment_executor ("tenant", "id"),
  FOREIGN KEY ("tenant", "evidence") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE fulfillment_start (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "fulfillment" TEXT COLLATE "C" NOT NULL,
  "began_at" TEXT COLLATE "C" NOT NULL,
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id")
);

CREATE TABLE fulfillment_end (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "fulfillment" TEXT COLLATE "C" NOT NULL,
  "start" TEXT COLLATE "C",
  "outcome" TEXT COLLATE "C" NOT NULL,
  "coverage" TEXT COLLATE "C" NOT NULL,
  "ended_at" TEXT COLLATE "C" NOT NULL,
  "evidence" TEXT COLLATE "C",
  "reason" TEXT COLLATE "C" NOT NULL,
  "recorded_by" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id"),
  FOREIGN KEY ("tenant", "start") REFERENCES fulfillment_start ("tenant", "id"),
  FOREIGN KEY ("tenant", "evidence") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE fulfillment_replacement (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "prior" TEXT COLLATE "C" NOT NULL,
  "prior_end" TEXT COLLATE "C" NOT NULL,
  "replacement" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "prior") REFERENCES fulfillment ("tenant", "id"),
  FOREIGN KEY ("tenant", "prior_end") REFERENCES fulfillment_end ("tenant", "id"),
  FOREIGN KEY ("tenant", "replacement") REFERENCES fulfillment ("tenant", "id")
);

CREATE TABLE fulfillment_task_link (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "fulfillment" TEXT COLLATE "C" NOT NULL,
  "queue" TEXT COLLATE "C" NOT NULL,
  "task" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment") REFERENCES fulfillment ("tenant", "id")
);

CREATE TABLE risk_assessment (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "risk" TEXT COLLATE "C" NOT NULL,
  "revision" BIGINT NOT NULL,
  "predecessor" TEXT COLLATE "C",
  "likelihood" TEXT COLLATE "C" NOT NULL,
  "impact" TEXT COLLATE "C" NOT NULL,
  "confidence" BIGINT NOT NULL,
  "evaluation" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "assessed_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "risk") REFERENCES risk ("tenant", "id"),
  FOREIGN KEY ("tenant", "predecessor") REFERENCES risk_assessment ("tenant", "id"),
  FOREIGN KEY ("tenant", "likelihood") REFERENCES risk_level ("tenant", "id"),
  FOREIGN KEY ("tenant", "impact") REFERENCES risk_level ("tenant", "id"),
  FOREIGN KEY ("tenant", "evaluation") REFERENCES evaluation_finish ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE risk_acceptance (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "assessment" TEXT COLLATE "C" NOT NULL,
  "decision_case" TEXT COLLATE "C" NOT NULL,
  "outcome" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "assessment") REFERENCES risk_assessment ("tenant", "id"),
  FOREIGN KEY ("tenant", "decision_case") REFERENCES decision_case ("tenant", "id"),
  FOREIGN KEY ("tenant", "outcome") REFERENCES decision_outcome ("tenant", "id")
);

CREATE TABLE risk_treatment (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "assessment" TEXT COLLATE "C" NOT NULL,
  "fulfillment_set" TEXT COLLATE "C" NOT NULL,
  "action" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "assessment") REFERENCES risk_assessment ("tenant", "id"),
  FOREIGN KEY ("tenant", "fulfillment_set") REFERENCES fulfillment_set ("tenant", "id")
);

CREATE TABLE residual_risk (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "treatment" TEXT COLLATE "C" NOT NULL,
  "baseline" TEXT COLLATE "C" NOT NULL,
  "residual" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "treatment") REFERENCES risk_treatment ("tenant", "id"),
  FOREIGN KEY ("tenant", "baseline") REFERENCES risk_assessment ("tenant", "id"),
  FOREIGN KEY ("tenant", "residual") REFERENCES risk_assessment ("tenant", "id")
);

CREATE TABLE trust_signal (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "subject" TEXT COLLATE "C" NOT NULL,
  "dimension" TEXT COLLATE "C" NOT NULL,
  "kind" TEXT COLLATE "C" NOT NULL,
  "issuer" TEXT COLLATE "C" NOT NULL,
  "source_record" TEXT COLLATE "C" NOT NULL,
  "observed_at" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "explanation" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "subject") REFERENCES trust_subject ("tenant", "id"),
  FOREIGN KEY ("tenant", "dimension") REFERENCES trust_dimension ("tenant", "id"),
  FOREIGN KEY ("tenant", "kind") REFERENCES signal_kind ("tenant", "id"),
  FOREIGN KEY ("tenant", "issuer") REFERENCES party ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE signal_correction (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "signal" TEXT COLLATE "C" NOT NULL,
  "replacement" TEXT COLLATE "C",
  "effective_at" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "signal") REFERENCES trust_signal ("tenant", "id"),
  FOREIGN KEY ("tenant", "replacement") REFERENCES trust_signal ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE signal_dispute (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "signal" TEXT COLLATE "C" NOT NULL,
  "raised_by" TEXT COLLATE "C" NOT NULL,
  "effective_at" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "signal") REFERENCES trust_signal ("tenant", "id"),
  FOREIGN KEY ("tenant", "raised_by") REFERENCES party ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE dispute_resolution (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "dispute" TEXT COLLATE "C" NOT NULL,
  "upheld" BIGINT NOT NULL,
  "effective_at" TEXT COLLATE "C" NOT NULL,
  "reason" TEXT COLLATE "C" NOT NULL,
  "support" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "dispute") REFERENCES signal_dispute ("tenant", "id"),
  FOREIGN KEY ("tenant", "support") REFERENCES evidence_seal ("tenant", "id")
);

CREATE TABLE signal_member (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "signal" TEXT COLLATE "C" NOT NULL,
  "rationale" TEXT COLLATE "C" NOT NULL,
  "next" TEXT COLLATE "C",
  "depth" BIGINT NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "signal") REFERENCES trust_signal ("tenant", "id"),
  FOREIGN KEY ("tenant", "next") REFERENCES signal_member ("tenant", "id")
);

CREATE TABLE trust_review (
  "tenant" TEXT COLLATE "C" NOT NULL,
  "id" TEXT COLLATE "C" NOT NULL,
  "subject" TEXT COLLATE "C" NOT NULL,
  "dimension" TEXT COLLATE "C" NOT NULL,
  "window_from" TEXT COLLATE "C" NOT NULL,
  "window_until" TEXT COLLATE "C" NOT NULL,
  "evaluations" TEXT COLLATE "C" NOT NULL,
  "head" TEXT COLLATE "C" NOT NULL,
  "created_at" TEXT COLLATE "C" NOT NULL,
  "updated_at" TEXT COLLATE "C" NOT NULL,
  PRIMARY KEY ("tenant", "id"),
  FOREIGN KEY ("tenant", "subject") REFERENCES trust_subject ("tenant", "id"),
  FOREIGN KEY ("tenant", "dimension") REFERENCES trust_dimension ("tenant", "id"),
  FOREIGN KEY ("tenant", "evaluations") REFERENCES evaluation_set ("tenant", "id"),
  FOREIGN KEY ("tenant", "head") REFERENCES signal_member ("tenant", "id")
